// Minimal argparse-style CLI parser (ESM, zero dependencies).
// Mirrors the verified behavior of the original script's argument handling:
// usage/errors on stderr with exit code 2, -h/--help on stdout with exit 0.

import { pyStr } from './pyrepr.mjs';

const SPECS = [
  { flag: '--k1', dest: 'k1', metavar: 'K1', type: 'str' },
  { flag: '--v1', dest: 'v1', metavar: 'V1', type: 'int' },
  { flag: '--k2', dest: 'k2', metavar: 'K2', type: 'str' },
  { flag: '--v2', dest: 'v2', metavar: 'V2', type: 'int' },
];

const BY_FLAG = {};
for (const spec of SPECS) BY_FLAG[spec.flag] = spec;

function usageLine(prog) {
  return `usage: ${prog} [-h] --k1 K1 --v1 V1 --k2 K2 --v2 V2`;
}

function fail(prog, message) {
  process.stderr.write(usageLine(prog) + '\n');
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function printHelp(prog) {
  const lines = [
    usageLine(prog),
    '',
    'options:',
    '  -h, --help  show this help message and exit',
  ];
  for (const spec of SPECS) {
    lines.push(`  ${spec.flag} ${spec.metavar}`);
  }
  process.stdout.write(lines.join('\n') + '\n');
  process.exit(0);
}

// Accepts an optional sign followed by digits only, with surrounding
// whitespace allowed; anything else is rejected as an invalid int value.
function parseIntValue(raw, flag, prog) {
  const trimmed = raw.trim();
  if (!/^[+-]?[0-9]+$/.test(trimmed)) {
    fail(prog, `argument ${flag}: invalid int value: ${pyStr(raw)}`);
  }
  return parseInt(trimmed, 10);
}

export function parseArgs(argv, prog) {
  const result = {};
  const extras = [];

  let i = 0;
  while (i < argv.length) {
    const token = argv[i];

    if (token === '-h' || token === '--help') {
      printHelp(prog);
    }

    let flag = token;
    let inlineValue = null;
    const eq = token.indexOf('=');
    if (token.startsWith('--') && eq !== -1) {
      flag = token.slice(0, eq);
      inlineValue = token.slice(eq + 1);
    }

    const spec = BY_FLAG[flag];
    if (!spec) {
      extras.push(token);
      i += 1;
      continue;
    }

    let rawValue;
    if (inlineValue !== null) {
      rawValue = inlineValue;
      i += 1;
    } else {
      if (i + 1 >= argv.length) {
        fail(prog, `argument ${spec.flag}: expected one argument`);
      }
      rawValue = argv[i + 1];
      i += 2;
    }

    result[spec.dest] =
      spec.type === 'int' ? parseIntValue(rawValue, spec.flag, prog) : rawValue;
  }

  const missing = SPECS.filter((spec) => !(spec.dest in result)).map(
    (spec) => spec.flag
  );
  if (missing.length > 0) {
    fail(prog, `the following arguments are required: ${missing.join(', ')}`);
  }

  if (extras.length > 0) {
    fail(prog, `unrecognized arguments: ${extras.join(' ')}`);
  }

  return { k1: result.k1, v1: result.v1, k2: result.k2, v2: result.v2 };
}

args.command:
cd /output && node --input-type=module -e "
import { parseArgs } from './lib/argparse.mjs';
const r = parseArgs(['--k1','e','--v1','23','--k2=s','--v2',' -7 '], 'test19.mjs');
console.log(JSON.stringify(r));
"

cd /output && node --input-type=module -e "
import { parseArgs } from './lib/argparse.mjs';
parseArgs(['--k1','e','--v1','23','--k2','s'], 'test19.mjs');
"; echo "exit=$?"

