import { parseArgs } from './lib/argparse.mjs';
parseArgs(['--k1','e','--v1','x','--k2','s','--v2','2'], 'test19.mjs');
"; echo "exit=$?"; node --input-type=module -e "
import { parseArgs } from './lib/argparse.mjs';
parseArgs(['--k1','e','--bogus','1'], 'test19.mjs');
"; echo "exit=$?"; node --input-type=module -e "
import { parseArgs } from './lib/argparse.mjs';
parseArgs(['--help'], 'test19.mjs');
"; echo "exit=$?"

